// Hand-written ripple-carry adder: N full adders chained, carry out dropped (wraps like +).
// Phase 3 candidate (generated by pd_flow/modules/ripple_add/layout_plan/gen_placement.py):
// under `SYNTHESIS (Yosys) the adder is instantiated GF180 7-track cells with stable names
// (bitslice[i].u_fa = addf_1 for bits 0..N-2, u_msb_x3 = xor3_1 for bit N-1); simulators and
// the Verilator linter compile the original behavioural body below.
module ripple_add #(parameter N = 16) (
    input  wire [N-1:0] a,
    input  wire [N-1:0] b,
    input  wire         cin,
    output wire [N-1:0] s
);
`ifdef SYNTHESIS
    wire [N-1:0] c;
    assign c[0] = cin;
    genvar i;
    generate
        for (i = 0; i < N - 1; i = i + 1) begin : bitslice
            gf180mcu_fd_sc_mcu7t5v0__addf_1 u_fa (.A(a[i]), .B(b[i]), .CI(c[i]), .S(s[i]), .CO(c[i + 1]));
        end
    endgenerate
    gf180mcu_fd_sc_mcu7t5v0__xor3_1 u_msb_x3 (.A1(c[N-1]), .A2(b[N-1]), .A3(a[N-1]), .Z(s[N-1]));
`else
    wire [N:0] c;
    assign c[0] = cin;
    genvar i;
    generate
        for (i = 0; i < N; i = i + 1) begin : fa
            assign s[i]     = a[i] ^ b[i] ^ c[i];
            assign c[i + 1] = (a[i] & b[i]) | (c[i] & (a[i] ^ b[i]));
        end
    endgenerate
`endif
endmodule
